SELECT *
FROM venue_occupation
WHERE venue_id = #{venueId}
  AND occupation_date BETWEEN #{startDate} AND #{endDate}
  AND status = #{status}
  AND deleted = 0
ORDER BY occupation_date ASC, start_time ASC

SELECT *
FROM venue_occupation
WHERE venue_id = #{venueId}
  AND occupation_date = #{occupationDate}
  AND status = #{status}
  AND deleted = 0
  AND start_time < #{endTime}
  AND end_time > #{startTime}

      AND NOT (business_id = #{excludeBusinessId})

ORDER BY start_time ASC
